import{_ as s,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ATLAS Icon Studio","description":"Gérer, importer, supprimer et enregistrer des jeux d’icônes Home Assistant avec ATLAS Icon Studio.","frontmatter":{"title":"ATLAS Icon Studio","description":"Gérer, importer, supprimer et enregistrer des jeux d’icônes Home Assistant avec ATLAS Icon Studio."},"headers":[],"relativePath":"fr/projects/atlas-plugins/icon-studio.md","filePath":"fr/projects/atlas-plugins/icon-studio.md","lastUpdated":1793128957000}'),a={name:"fr/projects/atlas-plugins/icon-studio.md"};function o(r,e,c,u,l,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="atlas-icon-studio" tabindex="-1">ATLAS Icon Studio <a class="header-anchor" href="#atlas-icon-studio" aria-label="Permalink to &quot;ATLAS Icon Studio&quot;">​</a></h1><p>ATLAS Icon Studio est un plugin installé séparément pour créer et gérer des jeux d’icônes Home Assistant avec le préfixe <code>atlas:</code>. La version 0.1.15 prend en charge les grandes collections sans limite fixe du nombre d’icônes ; la liste affiche 24 éléments à la fois.</p><h2 id="gestion-des-icones" tabindex="-1">Gestion des icônes <a class="header-anchor" href="#gestion-des-icones" aria-label="Permalink to &quot;Gestion des icônes&quot;">​</a></h2><p>Version actuelle du plugin : <strong>0.1.17</strong>. Elle corrige un import de validation manquant lors de la création de texte dans le dessin. La version 0.1.16 avait corrigé le démarrage du sélecteur d’export. Les formats de stockage restent inchangés.</p><p>La collection est dans IndexedDB local au navigateur. Les anciennes données sont reprises ; exporter en JSON avant de changer de navigateur ou d’adresse.</p><h2 id="dessin-et-apercu-d-images" tabindex="-1">Dessin et aperçu d’images <a class="header-anchor" href="#dessin-et-apercu-d-images" aria-label="Permalink to &quot;Dessin et aperçu d’images&quot;">​</a></h2><p>Une zone séparée crée des SVG en couleur avec formes, dessin libre et texte, ordre des calques et dix étapes d’annulation/rétablissement au maximum. Enregistrer sous exporte SVG, PNG ou WebP, avec fond transparent en option. Les images matricielles peuvent être affichées et vectorisées en option, mais ne deviennent pas directement des icônes <code>atlas:</code> ; le jeu HA nécessite des chemins SVG. File Studio transmet les images prises en charge à Icon Studio sur le même serveur ATLAS. Les téléchargements ne sont pas copiés automatiquement dans HA.</p><h2 id="modifier-la-collection" tabindex="-1">Modifier la collection <a class="header-anchor" href="#modifier-la-collection" aria-label="Permalink to &quot;Modifier la collection&quot;">​</a></h2><p>Sélectionnez une icône dans la collection et utilisez <strong>Supprimer l’icône</strong>. Icon Studio sélectionne ensuite automatiquement la prochaine icône supprimable. Vous pouvez ainsi en supprimer plusieurs à la suite sans devoir en sélectionner une après chaque suppression. L’icône de référence <code>atlas:home</code> est protégée et ne peut pas être supprimée. La collection conserve toujours au moins une icône.</p><p>La recherche, la navigation au clavier et l’export portent sur toute la collection, même si seule une petite partie est affichée. Les collections peuvent être sauvegardées et restaurées au format JSON ; les conflits de noms peuvent être remplacés, ignorés ou renommés automatiquement.</p><h2 id="home-assistant" tabindex="-1">Home Assistant <a class="header-anchor" href="#home-assistant" aria-label="Permalink to &quot;Home Assistant&quot;">​</a></h2><p>Les jeux d’icônes peuvent être exportés localement sous <code>atlas-iconset.js</code> ou lus directement depuis <code>/config/www/atlas-iconset.js</code> avec File Studio. Lors de l’enregistrement, vous pouvez remplacer le fichier existant ; File Studio crée d’abord une sauvegarde. Icon Studio peut aussi créer un nouveau fichier numéroté et afficher son chemin de ressource <code>/local/...</code> à enregistrer dans Home Assistant. L’accès direct nécessite que <code>/config/www</code> soit autorisé dans File Studio.</p><p>Consultez le <a href="https://github.com/rockbaer2007/atlas-icon-studio-plugin#readme" target="_blank" rel="noreferrer">README du plugin</a> pour les détails d’installation, de formats et de chemins.</p><h2 id="restauration-securisee-du-plugin" tabindex="-1">Restauration sécurisée du plugin <a class="header-anchor" href="#restauration-securisee-du-plugin" aria-label="Permalink to &quot;Restauration sécurisée du plugin&quot;">​</a></h2><p>Sauvegarder la collection en JSON, exporter le jeu d’icônes et enregistrer séparément les dessins en SVG. Dans <strong>Administration → Gestionnaire de plugins → Icon Studio → Restaurer</strong>, choisir une sauvegarde et vérifier version/compatibilité. L’action d’application sauvegarde aussi le plugin actuel. Annuler le conserve.</p><div class="info custom-block"><p class="custom-block-title">Vérification isolée du 16/10/2026</p><p>Avec ATLAS 0.1.312 : <strong>0.1.16 → 0.1.17</strong>, puis <strong>0.1.17 → 0.1.16 → 0.1.17 sauvegardée</strong>, redémarrage compris. Les douze fichiers correspondent aux paquets. Une collection de 131 icônes et un dessin avec deux textes sont conservés dans le même profil et à la même origine. Les nouveaux exports JSON, JavaScript et SVG sont identiques octet par octet. Création de texte, duplication et annulation fonctionnent. Fichiers de test, jeu existant, projet, autre plugin, corbeille et historique sont conservés. Dépôts, données serveur et exports du navigateur ont été sauvegardés avant les changements. <strong>Pi 5 et Proxmox n’ont été ni interrogés ni modifiés pendant cet essai isolé.</strong> Les migrations de format restent distinctes.</p></div><div class="info custom-block"><p class="custom-block-title">Vérification sur Pi 5 et Proxmox le 16/10/2026</p><p>Après sauvegardes HA locales, copies de fichiers sur PC et exports du navigateur, l’administration a validé <strong>0.1.16 → 0.1.17 → 0.1.16 d’origine → 0.1.17</strong>. Les douze fichiers du paquet correspondent ; paramètres, fichiers existants, six plugins actifs, projet, corbeille et historique sont conservés. ATLAS 0.1.312 et HA 2026.10.1 ne nécessitent aucun redémarrage. Les deux systèmes terminent avec Icon Studio 0.1.17. Si un aperçu de mise à jour périmé est refusé après une restauration, recharger l’administration puis sélectionner à nouveau la mise à jour. Accès direct et HA Ingress vérifiés sur chaque hôte : trois icônes de référence et un brouillon vide par contexte. Le JSON de collection reste identique octet par octet et le brouillon est inchangé après rechargement. Création de texte et annulation fonctionnent. Les grandes collections et dessins remplis ont été vérifiés dans l’essai isolé.</p></div><p>Restaurer le paquet ne restaure pas les données supprimées du navigateur. IndexedDB et le brouillon local dépendent du profil et de l’origine (protocole, hôte et port). Une sauvegarde HA/serveur ne contient pas ces données. JSON de collection et JavaScript d’icônes excluent les dessins en couleur ; le SVG exporté n’est pas une sauvegarde complète du brouillon modifiable et des annulations. Formes et nom du fichier courant persistent localement ; outils, recherche et historique d’annulation/rétablissement appartiennent à la session.</p>',18)])])}const g=s(a,[["render",o]]);export{m as __pageData,g as default};
